  background: linear-gradient(180deg, rgba(255, 255, 255, 0.7) 0%, rgba(240, 253, 250, 0.3) 100%);
  border: 2px solid rgba(255, 255, 255, 0.8);
  border-radius: 8px;
  padding: 2px 8px;
  color: #0369a1;
  font-weight: bold;
  box-shadow: 1px 2px 4px rgba(0, 0, 0, 0.1), inset 0 1px 0 #fff, inset 0 -3px 6px rgba(2, 132, 199, 0.1);
  display: inline-block;
  transition: background-color 0.35s ease, border-color 0.35s ease;
}

/* --- 4. Kinetic Horizontal Wave Oscillation --- */
.kinetic-wave-text {
  display: inline-flex !important;
  gap: 1px;
  font-weight: bold;
  color: #10b981;
}

.kinetic-wave-char {
  display: inline-block;
  animation: wave-bounce 1.2s infinite ease-in-out;
}

@keyframes wave-bounce {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px) scale(1.1);
    color: #34d399;
    text-shadow: 0 4px 8px rgba(52, 211, 153, 0.5);
  }
}
/* --- 3D Edit-Safe Aqua Box Container Frame --- */
.aqua-aero-box {
  background: radial-gradient(circle at 50% 30%, #06b6d4 0%, #0284c7 70%, #0369a1 100%);
  border: 3px solid #67e8f9;
  border-radius: 16px;
  padding: 25px;
  margin: 20px 0;
  color: #ffffff;
  font-weight: bold;
  position: relative;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(6, 182, 212, 0.4), inset 0 1px 2px rgba(255, 255, 255, 0.8), inset 0 -10px 20px rgba(0, 0, 0, 0.2);
  transition: background-color 0.35s ease, border-color 0.35s ease;
}

/* High-gloss top reflection lens overlay */
.aqua-aero-box::before {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  right: 2px;
  height: 45%;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.7) 0%, rgba(255, 255, 255, 0) 100%);
  border-radius: 13px 13px 100% 100%/13px 13px 30% 30%;
  pointer-events: none;
  z-index: 3;
  transition: background-color 0.35s ease, border-color 0.35s ease;
}

/* --- Inline Floating Aqua Orbs --- */
.aero-box-orb {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  z-index: 2;
  background: radial-gradient(circle at 50% 35%, rgba(255, 255, 255, 0.9) 0%, rgba(56, 189, 248, 0.4) 40%, rgba(2, 132, 199, 0.7) 80%, transparent 100%);
  box-shadow: inset -2px -2px 6px rgba(0, 0, 0, 0.2), 0 4px 10px rgba(6, 182, 212, 0.3);
  animation: bubble-up 5s infinite linear;
  opacity: 0.7;
  transition: background-color 0.35s ease, border-color 0.35s ease;
}

@keyframes bubble-up {
  0% {
    transform: translateY(120%) scale(0.7);
    opacity: 0;
  }
  10% {
    opacity: 0.7;
  }
  90% {
    opacity: 0.7;
  }
  100% {
    transform: translateY(-120%) scale(1.2);
    opacity: 0;
  }
}
/* --- The Edit-Safe Text Layer Window --- */
.aqua-box-content {
  position: relative;
  z-index: 4; /* Floats safely on top of bubbles */
  text-shadow: 0 2px 4px rgba(2, 44, 87, 0.8);
  font-family: "Segoe UI", sans-serif;
  line-height: 1.6;
