  transition: background-color 0.35s ease, border-color 0.35s ease;
}

/* 6. Mechanical Metallic Grid Mesh (~MM~) */
.effect-metallic-mesh {
  background-color: #94a3b8;
  background-image: radial-gradient(#64748b 1px, transparent 1px);
  background-size: 4px 4px;
  border: 2px solid #475569;
  border-bottom: 4px solid #334155;
  border-radius: 6px;
  padding: 2px 10px;
  color: #0f172a;
  font-weight: 800;
  white-space: nowrap;
  display: inline-block;
  text-shadow: 0 1px 0 #fff;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  transition: background-color 0.35s ease, border-color 0.35s ease;
}

/* 7. Kinetic Fluid Bubble Expand Ribbon (~FE~) */
.effect-fluid-expand {
  background: linear-gradient(180deg, #22d3ee 0%, #06b6d4 100%);
  border: 2px solid #99f6e4;
  border-radius: 12px;
  padding: 2px 12px;
  color: #042f2e;
  font-weight: bold;
  white-space: nowrap;
  display: inline-block;
  box-shadow: inset 0 1px 1px #fff, 0 3px 6px rgba(6, 182, 212, 0.2);
  animation: bubble-swell 2s infinite ease-in-out alternate;
  transition: background-color 0.35s ease, border-color 0.35s ease;
}

@keyframes bubble-swell {
  from {
    transform: scale(1);
    filter: brightness(1);
  }
  to {
    transform: scale(1.05);
    filter: brightness(1.15);
    box-shadow: inset 0 1px 2px #fff, 0 5px 12px rgba(6, 182, 212, 0.4);
  }
}
/* --- 3D State-Flipping Toggle Applet (~TB~) --- */
.applet-state-button {
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  padding: 3px 14px;
  border-radius: 20px; /* Capsule shape matching your style theme */
