/* --- Linkable footnote chips! --- */
.kd-footnote-ref {
  font-size: 0.78em;
  vertical-align: super;
  line-height: 1;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.6), rgba(255, 255, 255, 0) 50%), rgba(125, 211, 252, 0.55);
  border: 1px solid #0284c7;
  border-radius: 8px;
  padding: 0 5px;
  text-decoration: none;
  color: #0c4a6e;
  font-weight: 800;
  cursor: pointer;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7), 0 1px 3px rgba(2, 132, 199, 0.3);
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}

.kd-footnote-tag {
  display: inline-block;
  background: #0284c7;
  color: #fff;
  font-weight: 900;
  font-size: 0.78em;
  border-radius: 6px;
  padding: 0 6px;
  margin-right: 6px;
}

.kd-footnote-def {
  background: rgba(224, 242, 254, 0.35);
  border-left: 3px solid #0284c7;
  border-radius: 0 8px 8px 0;
  margin: 8px 0;
  padding: 6px 10px;
  font-size: 0.88em;
  color: #0c4a6e;
}

.kd-footnote-back {
  text-decoration: none;
  color: #0284c7;
  font-weight: 900;
  margin-right: 6px;
  cursor: pointer;
}

/* ---------- 2. Marketplace Keydown packs ---------- */
/* Marketplace: Neon Ribbon Pack */
.mkt-neon-ribbon{display:inline-flex!important;align-items:center;padding:2px 10px;border-radius:20px;font-weight:800;white-space:nowrap;margin:0 2px;vertical-align:middle;color:#fff;background:linear-gradient(90deg,#06b6d4,#8b5cf6,#ec4899,#06b6d4);background-size:200% auto;border:2px solid rgba(255,255,255,0.7);text-shadow:0 1px 2px rgba(0,0,0,0.4);box-shadow:0 0 12px rgba(139,92,246,0.55),inset 0 1px 1px rgba(255,255,255,0.6);animation:mkt-neon-slide 3s linear infinite;}@keyframes mkt-neon-slide{to{background-position:200% center;}}
/* Marketplace: Pastel Gel Chips */
.mkt-pastel-pop{display:inline-flex!important;align-items:center;padding:2px 10px;border-radius:10px;font-weight:800;white-space:nowrap;margin:0 2px;vertical-align:middle;background:linear-gradient(180deg,#fce7f3 0%,#f9a8d4 100%);border:2px solid #ec4899;color:#831843;box-shadow:0 3px 6px rgba(0,0,0,0.06),inset 0 1px 1px rgba(255,255,255,0.7);}
/* Marketplace: Holographic Chip */
