.outline-section.collapsed .outline-toggle svg { transform: rotate(-90deg); }
.outline-item-l2 { padding-left: 22px; }
.outline-item-l3 { padding-left: 34px; }
.tab-rename-input { width: 100%; box-sizing: border-box; background: rgba(255, 255, 255, 0.12); border: 1px solid rgb(125, 211, 252); border-radius: 6px; color: rgb(255, 255, 255); padding: 3px 6px; font-size: 0.8rem; font-weight: 600; font-family: "JetBrains Mono", "Courier New", Courier, monospace; outline: none; }
.tab-head { margin-left: 26px; font-weight: 500; }
.kd-content h1 { color: rgb(2, 132, 199); font-weight: 800; border-bottom: 3px solid rgb(56, 189, 248); padding-bottom: 6px; margin: 15px 0px; }
.kd-content h2 { color: rgb(5, 150, 105); font-weight: 700; margin: 20px 0px 8px; }
.kd-content h3 { color: rgb(217, 119, 6); font-size: 18px; margin: 15px 0px 5px; }
.kd-content blockquote { background: linear-gradient(90deg, rgba(56, 189, 248, 0.15) 0%, rgba(255, 255, 255, 0) 100%); border-left: 5px solid rgb(2, 132, 199); margin: 15px 0px; padding: 10px 20px; color: rgb(3, 105, 161); font-style: italic; border-radius: 0px 8px 8px 0px; transition: background-color 0.35s, border-color 0.35s; }
