.bbcss-chip { display: inline-block; position: relative; padding: 1px 10px; margin: 0px 2px; border-radius: 8px; line-height: 1.45; vertical-align: baseline; caret-color: currentcolor; }
@media (prefers-reduced-motion: reduce) {
  .bbcss-chip { animation: auto ease 0s 1 normal none running none !important; }
}
.cs-grid .us-tile-stage { min-height: 38px; padding: 0px 4px; }
.cs-grid .us-tile-stage .bbcss-chip, .us-preview-stage .bbcss-chip { pointer-events: none; }
.cs-col { border-radius: 2px; padding-bottom: 4px; background: linear-gradient(var(--c), var(--c)) left bottom / 100% 3px no-repeat,
        linear-gradient(rgba(255, 255, 255, 0.6), rgba(255, 255, 255, 0.6)) left bottom / 100% 3px no-repeat; }
.cs-col.on { outline: rgba(255, 255, 255, 0.35) solid 1px; outline-offset: 1px; }
.cs-code-ok { color: rgb(21, 128, 61); }
.cs-code-bad { color: rgb(180, 83, 9); margin-top: 2px; }
.cs-saved-empty { margin: 4px 0px; font-size: 12px; color: rgb(126, 34, 206); }
.cs-saved-row { display: flex; align-items: center; gap: 8px; padding: 4px 6px; border-radius: 8px; background: rgb(255, 255, 255); border: 1px solid rgb(243, 232, 255); }
.cs-saved-stage { flex: 0 0 auto; min-width: 70px; display: flex; justify-content: center; font-size: 12px; }
.cs-saved-stage .bbcss-chip { pointer-events: none; }
.cs-saved-name { flex: 1 1 auto; min-width: 0px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; font-weight: 800; color: rgb(88, 28, 135); }
.cs-saved-del.armed { background: rgb(254, 226, 226); border-color: rgb(248, 113, 113); color: rgb(185, 28, 28); }
.cs-find-grid .us-tile-stage { overflow: hidden; }
.cs-find-grid .us-tile-stage > * { pointer-events: none; max-width: 100%; }
.cs-find-line { display: inline-block; max-width: 100%; }
.cs-find-head .us-preview-stage > * { pointer-events: none; }
.csi-row { flex: 0 0 auto; display: flex; align-items: flex-start; gap: 10px; padding: 6px 8px; border-radius: 8px; background: rgb(255, 255, 255); border: 1px solid rgb(243, 232, 255); }
.csi-row.bad { border-color: rgb(252, 211, 77); background: rgb(255, 251, 235); }
.csi-label { flex: 0 0 11ch; line-height: 30px; font-size: 12px; font-weight: 800; color: rgb(88, 28, 135); }
.csi-value { flex: 1 1 auto; min-width: 0px; font: 12px / 30px "JetBrains Mono", monospace; color: rgb(71, 85, 105); }
.csi-text { white-space: pre-wrap; overflow-wrap: anywhere; }
.csi-break { display: block; height: 4px; }
.csi-tools { flex: 0 0 auto; display: flex; align-items: center; gap: 4px; }
.csi-color { display: inline-flex; align-items: center; gap: 5px; margin: 0px 2px; padding: 0px 8px 0px 3px; height: 24px; vertical-align: middle; box-sizing: border-box; border: 1px solid rgb(216, 180, 254); border-radius: 999px; background: rgb(255, 255, 255); color: rgb(88, 28, 135); font: inherit; cursor: pointer; }
.csi-color:hover { border-color: rgb(147, 51, 234); }
.csi-color:focus-visible { outline: rgb(147, 51, 234) solid 2px; outline-offset: 1px; }
.csi-num { display: inline-flex; align-items: center; gap: 2px; margin: 0px 2px; vertical-align: middle; line-height: 1; }
.csi-num-in { min-width: 0px; height: 24px; box-sizing: border-box; padding: 0px 4px; border: 1px solid rgb(216, 180, 254); border-radius: 6px; background: rgb(250, 245, 255); color: rgb(88, 28, 135); font: inherit; }
.csi-num-in { appearance: textfield; text-align: center; }
.csi-num-in::-webkit-inner-spin-button, .csi-num-in::-webkit-outer-spin-button { appearance: none; margin: 0px; }
.csi-num-in:focus { outline: none; border-color: rgb(147, 51, 234); box-shadow: rgba(147, 51, 234, 0.25) 0px 0px 0px 2px; }
.csi-unit { color: rgb(126, 34, 206); font-weight: 700; }
.csi-warn { flex: 0 0 auto; color: rgb(180, 83, 9); font-weight: 800; cursor: help; }
.csi-kw { height: 24px; margin: 0px 2px; padding: 0px 4px; vertical-align: middle; box-sizing: border-box; border: 1px solid rgb(216, 180, 254); border-radius: 6px; background: rgb(250, 245, 255); color: rgb(88, 28, 135); font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-size: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; line-height: normal; cursor: pointer; }
.csi-kw:focus { outline: none; border-color: rgb(147, 51, 234); box-shadow: rgba(147, 51, 234, 0.25) 0px 0px 0px 2px; }
.csi-grad { display: block; margin: 2px 0px; padding: 6px 8px; border-radius: 6px; background: rgba(59, 130, 246, 0.12); color: rgb(29, 78, 216); line-height: normal; }
.csi-grad-head { display: flex; align-items: center; gap: 8px; }
.csi-grad-name { flex: 0 0 auto; font-size: 11px; font-weight: 700; }
.csi-grad-preview { flex: 1 1 auto; min-width: 40px; height: 12px; border-radius: 4px; border: 1px solid rgba(29, 78, 216, 0.25); background-color: rgb(255, 255, 255); }
.csi-grad-preview.csi-grad-novar { background: repeating-linear-gradient(45deg, rgba(29, 78, 216, 0.08) 0px, rgba(29, 78, 216, 0.08) 6px, transparent 6px, transparent 12px); }
.csi-grad-args { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 6px; }
.csi-grad-arg { display: inline-flex; flex-wrap: wrap; align-items: center; min-height: 28px; padding: 2px 6px; border-radius: 6px; background: rgba(255, 255, 255, 0.75); color: rgb(30, 58, 138); }
.csi-grad-arg .csi-text { white-space: pre; }
.csi-var-wrap { display: inline; }
.csi-var { display: inline-flex; align-items: center; height: 22px; margin: 0px 2px; padding: 0px 9px; vertical-align: middle; box-sizing: border-box; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 999px; background: rgb(224, 231, 255); color: rgb(55, 48, 163); font-style: inherit; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: 0.85em; font-weight: 800; letter-spacing: 0.04em; cursor: pointer; }
.csi-var:hover { background: rgb(199, 210, 254); }
.csi-var:focus-visible { outline: rgb(79, 70, 229) solid 2px; outline-offset: 1px; }
.csi-var-or { color: rgb(99, 102, 241); }
.csi-func { display: inline; margin: 0px 2px; padding: 3px 6px; border-radius: 6px; line-height: 30px; background: rgba(16, 185, 129, 0.12); color: rgb(4, 120, 87); -webkit-box-decoration-break: clone; box-decoration-break: clone; }
.csi-func-name { margin-right: 4px; font-size: 11px; font-weight: 700; }
.csi-func .csi-text { color: rgb(6, 95, 70); }
.csi-raw { flex: 1 1 auto; width: 100%; padding: 4px 6px; font: 12px "JetBrains Mono", monospace; }
.csi-group { margin-top: 6px; }
@media (max-width: 620px) {
  .csi-label { min-width: 0px; }
}
.font-pick-head { margin: 8px 6px 4px; font-size: 10px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: rgb(147, 51, 234); }
.font-pick-row { display: flex; align-items: center; gap: 4px; }
.font-pick-item { flex: 1 1 auto; min-width: 0px; padding: 7px 10px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 8px; background: transparent; color: rgb(59, 7, 100); font-size: 15px; text-align: left; cursor: pointer; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.font-pick-item:hover, .font-pick-item:focus-visible { background: rgb(243, 232, 255); outline: none; }
.font-pick-item.on { background: linear-gradient(rgb(192, 132, 252) 0%, rgb(147, 51, 234) 100%); color: rgb(255, 255, 255); }
.font-pick-kind { flex: 0 0 auto; padding: 1px 6px; border-radius: 999px; background: rgb(243, 232, 255); color: rgb(107, 33, 168); font-size: 9px; font-weight: 800; text-transform: uppercase; }
.font-pick-x { flex: 0 0 auto; width: 24px; height: 24px; padding: 0px; border: 1px solid rgb(233, 213, 255); border-radius: 6px; background: rgb(255, 255, 255); color: rgb(107, 33, 168); cursor: pointer; }
.font-pick-x:hover { border-color: rgb(248, 113, 113); color: rgb(185, 28, 28); }
.font-pick-empty { margin: 2px 10px 6px; font-size: 11px; color: rgb(107, 33, 168); }
.font-pick-adds { margin-top: 6px; padding-top: 4px; border-top: 1px solid rgb(233, 213, 255); display: flex; flex-direction: column; gap: 6px; }
.font-pick-sysrow { display: flex; gap: 6px; padding: 0px 4px; }
.font-pick-input { flex: 1 1 auto; min-width: 0px; padding: 6px 8px; border: 1px solid rgb(216, 180, 254); border-radius: 8px; background: rgb(255, 255, 255); color: rgb(59, 7, 100); font: 12px "JetBrains Mono", monospace; }
.font-pick-input:focus { outline: none; border-color: rgb(147, 51, 234); box-shadow: rgba(147, 51, 234, 0.2) 0px 0px 0px 3px; }
.font-pick-action { margin: 0px 4px; padding: 6px 10px; border: 1px solid rgb(216, 180, 254); border-radius: 8px; cursor: pointer; background: linear-gradient(rgb(255, 255, 255) 0%, rgb(243, 232, 255) 100%); color: rgb(107, 33, 168); font: 700 12px "JetBrains Mono", monospace; text-align: left; }
.font-pick-action:hover { background: linear-gradient(rgb(192, 132, 252) 0%, rgb(147, 51, 234) 100%); color: rgb(255, 255, 255); border-color: rgb(147, 51, 234); }
.font-pick-sysrow .font-pick-action { margin: 0px; flex: 0 0 auto; }
.font-pick-browse { display: flex; flex-direction: column; gap: 4px; padding: 0px 4px; }
.font-pick-browse[hidden] { display: none; }
.font-pick-results { max-height: 180px; overflow-y: auto; display: flex; flex-direction: column; }
.font-pick-msg { min-height: 1em; margin: 0px 6px 4px; font-size: 11px; font-weight: 700; color: rgb(4, 120, 87); }
.font-pick-msg.bad { color: rgb(180, 83, 9); }
@keyframes liquid-wobble { 
  0%, 100% { transform: scale(1) translateY(0px); }
  50% { transform: scale(1.04) translateY(-2px); }
}
@keyframes bubble-up { 
  0% { transform: translateY(120%) scale(0.7); opacity: 0; }
  10% { opacity: 0.7; }
  100% { transform: translateY(-120%) scale(1.2); opacity: 0; }
}
@keyframes bb-chip-eq { 
  0% { background-size: 3px 40%, 3px 90%, 3px 60%; }
  100% { background-size: 3px 100%, 3px 30%, 3px 85%; }
}
@keyframes bb-spin { 
  100% { transform: rotate(360deg); }
}
@keyframes bb-synth-pulse { 
  0%, 100% { box-shadow: rgba(255, 63, 180, 0.5) 0px 0px 6px, rgba(255, 63, 180, 0.18) 0px -6px 10px inset; }
  50% { box-shadow: rgba(255, 63, 180, 0.9) 0px 0px 14px, rgba(95, 246, 255, 0.8) 0px 0px 4px, rgba(255, 63, 180, 0.3) 0px -6px 10px inset; }
}
@keyframes tc-scan { 
  0% { background-position: 130% 0px, 0px 0px, 0px 0px; }
  100% { background-position: -130% 0px, 0px 0px, 0px 0px; }
}
@keyframes tc-spin { 
  100% { transform: rotate(360deg); }
}
@keyframes tc-core { 
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.35); }
}
@keyframes tc-ready-glow { 
  0%, 100% { box-shadow: rgba(124, 58, 237, 0.35) 0px 0px 0px 1px, rgba(52, 255, 170, 0.35) 0px 0px 6px, rgba(52, 255, 170, 0.15) 0px 0px 8px inset; }
  50% { box-shadow: rgba(124, 58, 237, 0.35) 0px 0px 0px 1px, rgba(52, 255, 170, 0.75) 0px 0px 14px, rgba(52, 255, 170, 0.3) 0px 0px 10px inset; }
}
@keyframes tc-shake { 
  0%, 100% { transform: translateX(0px); filter: none; }
  20% { transform: translateX(-3px) skewX(-6deg); filter: hue-rotate(60deg); }
  40% { transform: translateX(3px) skewX(6deg); filter: hue-rotate(-60deg) brightness(1.3); }
  60% { transform: translateX(-2px); filter: hue-rotate(30deg); }
  80% { transform: translateX(2px) skewX(3deg); filter: none; }
}
@keyframes us-sheen { 
  0%, 100% { background-position: 100% 0px, 0px 0px; }
  50% { background-position: -50% 0px, 0px 0px; }
}
@keyframes us-aurora { 
  0% { background-position: 0% 0%; }
  100% { background-position: 100% 100%; }
}
@keyframes us-ring { 
  0% { background-position: 0px 0px, 0px 0px; }
  100% { background-position: 0px 0px, 300% 0px; }
}
@keyframes us-barber { 
  0% { background-position: 0px 0px; }
  100% { background-position: 34px 0px; }
}
@keyframes us-loading { 
  0% { background-position: 0px 0px, 0px 0px; }
  100% { background-position: 17px 0px, 0px 0px; }
}
@keyframes us-rise { 
  0% { background-position: 0px 0px, 0px 0px, 0px 0px, 0px 0px, 0px 0px; }
  100% { background-position: 0px -20px, 0px -20px, 0px -20px, 0px -20px, 0px 0px; }
}
@keyframes us-progress { 
  0% { background-position: 0px 0px, 100% 0px, 0px 0px; }
  100% { background-position: 0px 0px, -120% 0px, 0px 0px; }
}
@keyframes us-fall { 
  0% { background-position: 0px 0px, 0px 0px; }
  100% { background-position: 0px 100%, 0px 0px; }
}
@keyframes us-blink { 
  0% { opacity: 1; }
  100% { opacity: 0.25; }
}
@keyframes us-pulse { 
  0% { box-shadow: rgba(255, 255, 255, 0.75) 0px 0px 0px 0px; }
  100% { box-shadow: rgba(255, 255, 255, 0) 0px 0px 0px 6px; }
}
@keyframes us-shimmer { 
  0% { background-position: 100% 0px; }
  100% { background-position: -150% 0px; }
}
@keyframes pm-done { 
  0%, 100% { box-shadow: rgba(0, 0, 0, 0.25) 0px 2px 4px; }
  50% { box-shadow: rgba(251, 191, 36, 0.45) 0px 0px 0px 4px, rgba(0, 0, 0, 0.25) 0px 2px 4px; }
}
@keyframes dc-tumble { 
  0% { transform: rotate(0deg) scale(1); }
  50% { transform: rotate(200deg) scale(1.25); }
  100% { transform: rotate(360deg) scale(1); }
}
@keyframes jumper-flash-ring { 
  0% { background: rgba(217, 70, 239, 0.35); box-shadow: rgba(217, 70, 239, 0.55) 0px 0px 0px 3px; }
  100% { background: transparent; box-shadow: rgba(217, 70, 239, 0) 0px 0px 0px 0px; }
}
